// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Img } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type PropertyAnimationProps = Record<string, any>;

const PropertyAnimation: React.FC<PropertyAnimationProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 8,
  heroImage = "https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?ixlib=rb-4.0.3&auto=format&fit=crop&w=1920&q=80",
  gridImages = [
    "https://images.unsplash.com/photo-1512917774080-9991f1c4c750?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
    "https://images.unsplash.com/photo-1600585154340-be6161a56a0c?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
    "https://images.unsplash.com/photo-1583608205776-bfd35f0d9f83?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
    "https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
    "https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
    "https://images.unsplash.com/photo-1513694203232-719a280e022f?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
    "https://images.unsplash.com/photo-1600585153490-76fb20a32601?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
    "https://images.unsplash.com/photo-1564013799919-ab600027ffc6?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
    "https://images.unsplash.com/photo-1570129477492-45c003edd2be?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
    "https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
  ],
  mainTitle = "Levon Court",
  mainAddress = "Atlanta, GA 30115",
  mainStats = "4 bed 2.5 bath 2,297 sq ft",
  messageLine1 = "Shop 60,000",
  messageLine2 = "homes",
  messageLine3 = "nationwide",
  messageBgColor = "#eaf4fc",
  messageTextColor = "#005288",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Constants for Grid Layout
  const COL_W = 380;
  const ROW_H = 460;
  const GAP_X = 30;
  const GAP_Y = 30;
  
  // Calculate starting positions to center the 4x3 grid
  const TOTAL_GRID_W = 4 * COL_W + 3 * GAP_X;
  const START_X = (width - TOTAL_GRID_W) / 2; // ~140
  
  // Center row 1 vertically
  const ROW_1_Y = (height - ROW_H) / 2; // ~310
  const START_Y = ROW_1_Y - ROW_H - GAP_Y; // Row 0 Y

  // Helper functions for positions
  const getColX = (col: number) => START_X + col * (COL_W + GAP_X);
  const getRowY = (row: number) => START_Y + row * (ROW_H + GAP_Y);

  // Animation Timings (in frames)
  const INTRO_START = 0;
  const MOVE_START = 80;
  const GRID_REVEAL_START = 95;

  // --- Main Card Animation Logic ---
  // 1. Morph from fullscreen to centered card
  const introProgress = spring({
    frame: frame - INTRO_START,
    fps,
    config: { damping: 16, mass: 0.8 },
    durationInFrames: 60,
  });

  // 2. Move from center to grid position (Row 1, Col 0)
  const moveProgress = spring({
    frame: frame - MOVE_START,
    fps,
    config: { damping: 14, stiffness: 90 },
  });

  // Main Card Dimensions & Position interpolations
  const centeredX = (width - COL_W) / 2;
  const gridPosX = getColX(0);
  
  const cardW = interpolate(introProgress, [0, 1], [width, COL_W]);
  const cardH = interpolate(introProgress, [0, 1], [height, ROW_H]);
  
  const currentCardX = interpolate(introProgress, [0, 1], [0, centeredX]) - 
                       interpolate(moveProgress, [0, 1], [0, centeredX - gridPosX]);
                       
  const currentCardY = interpolate(introProgress, [0, 1], [0, ROW_1_Y]);
  const imgH = interpolate(introProgress, [0, 1], [height, 240]);
  const borderRadius = interpolate(introProgress, [0, 1], [0, 16]);
  
  const detailsOpacity = interpolate(introProgress, [0.7, 1], [0, 1]);
  const badgeOpacity = interpolate(introProgress, [0.8, 1], [0, 1]);
  const shadowOpacity = interpolate(introProgress, [0.5, 1], [0, 0.1]);

  // Badges data
  const badges = [
    { text: "Brand new home", bg: "#d32f2f" },
    { text: "AMH Prelease", bg: "#388e3c" },
    { text: "Coming soon", bg: "#1976d2" },
  ];

  // Helper to get image safely
  const getImg = (index: number) => gridImages[index % gridImages.length];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: "hidden" }}>
      
      {/* Grid Elements (rendered underneath main card) */}
      {[0, 1, 2].map((row) => (
        [0, 1, 2, 3].map((col) => {
          // Skip the main card slot
          if (row === 1 && col === 0) return null;

          const isMessageCard = row === 1 && col === 1;
          const itemIndex = row * 4 + col;
          
          // Staggered animation for grid items based on distance from main card
          const delay = GRID_REVEAL_START + (col * 4) + (Math.abs(row - 1) * 6);
          
          const revealProgress = spring({
            frame: frame - delay,
            fps,
            config: { damping: 12, mass: 0.5 },
          });

          const itemScale = interpolate(revealProgress, [0, 1], [0.9, 1]);
          const itemOpacity = interpolate(revealProgress, [0, 1], [0, 1]);
          const itemYOffset = interpolate(revealProgress, [0, 1], [20, 0]);

          const x = getColX(col);
          const y = getRowY(row) + itemYOffset;
          const badge = badges[itemIndex % badges.length];

          return (
            <div
              key={`${row}-${col}`}
              style={{
                position: "absolute",
                left: x,
                top: y,
                width: COL_W,
                height: ROW_H,
                backgroundColor: isMessageCard ? messageBgColor : "#ffffff",
                borderRadius: 16,
                boxShadow: "0 10px 30px rgba(0,0,0,0.06)",
                opacity: itemOpacity,
                transform: `scale(${itemScale})`,
                overflow: "hidden",
                display: "flex",
                flexDirection: "column",
                transition: "none",
              }}
            >
              {isMessageCard ? (
                <div style={{ padding: "48px 40px", display: "flex", flexDirection: "column", justifyContent: "center", height: "100%" }}>
                  <div style={{ color: messageTextColor, fontSize: 44, fontWeight: 800, lineHeight: 1.15, letterSpacing: "-0.02em" }}>
                    <div>{messageLine1}</div>
                    <div>{messageLine2}</div>
                    <div>{messageLine3}</div>
                  </div>
                </div>
              ) : (
                <>
                  <div style={{ width: "100%", height: 240, position: "relative" }}>
                    <Img 
                      src={getImg(itemIndex)} 
                      style={{ width: "100%", height: "100%", objectFit: "cover" }} 
                    />
                    <div style={{
                      position: "absolute",
                      top: 16,
                      left: 16,
                      backgroundColor: badge.bg,
                      color: "#fff",
                      padding: "4px 12px",
                      borderRadius: 20,
                      fontSize: 14,
                      fontWeight: 600,
                    }}>
                      {badge.text}
                    </div>
                  </div>
                  <div style={{ padding: "24px 24px 0 24px" }}>
                    <div style={{ fontSize: 22, fontWeight: 500, color: "#111", marginBottom: 4 }}>
                      {mainTitle}
                    </div>
                    <div style={{ fontSize: 22, color: "#111", marginBottom: 16 }}>
                      {mainAddress}
                    </div>
                    <div style={{ fontSize: 16, color: "#777" }}>
                      {mainStats}
                    </div>
                  </div>
                </>
              )}
            </div>
          );
        })
      ))}

      {/* Main Hero Card (Animated from fullscreen) */}
      <div
        style={{
          position: "absolute",
          left: currentCardX,
          top: currentCardY,
          width: cardW,
          height: cardH,
          backgroundColor: "#ffffff",
          borderRadius: borderRadius,
          boxShadow: `0 20px 50px rgba(0,0,0,${shadowOpacity})`,
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          transition: "none",
          zIndex: 10, // Keep above grid during move
        }}
      >
        <div style={{ width: "100%", height: imgH, position: "relative" }}>
          <Img 
            src={heroImage} 
            style={{ width: "100%", height: "100%", objectFit: "cover" }} 
          />
          <div style={{
            position: "absolute",
            top: 16,
            left: 16,
            backgroundColor: "#d32f2f", // Red badge for main card
            color: "#fff",
            padding: "4px 12px",
            borderRadius: 20,
            fontSize: 14,
            fontWeight: 600,
            opacity: badgeOpacity,
          }}>
            Brand new home
          </div>
        </div>
        
        <div style={{ 
          padding: "24px 24px 0 24px", 
          opacity: detailsOpacity,
          display: "flex",
          flexDirection: "column",
        }}>
          <div style={{ fontSize: 22, fontWeight: 500, color: "#111", marginBottom: 4 }}>
            {mainTitle}
          </div>
          <div style={{ fontSize: 22, color: "#111", marginBottom: 16 }}>
            {mainAddress}
          </div>
          <div style={{ fontSize: 16, color: "#777" }}>
            {mainStats}
          </div>
        </div>
      </div>

    </AbsoluteFill>
  );
};

export default PropertyAnimation;